#!/usr/bin/env python3
"""Persist independent witnesses only after exact RDF4J commit acknowledgments."""
# Some portions generated by Codex
import json
import os
from pathlib import Path
import subprocess
import time

ROOT = Path("/mnt/run-results")
CLASS_DIR = Path(os.environ["RDF4J_CRASHLAB_CLASS_DIR"])
CP = str(CLASS_DIR) + ":" + (ROOT / "actual-build-classpath-guest.txt").read_text().strip()
BASE_EXPECTED = (ROOT / "actual-expected-witness.tsv").read_text().splitlines()
FOLLOWUP_EXPECTED = (ROOT / "actual-expected-followup-witness.tsv").read_text().splitlines()
WITNESS = ROOT / "actual-ack-witness.tsv"
NAMESPACE_WITNESS = ROOT / "actual-namespace-witness.tsv"
LOG = ROOT / "actual-writer-controller.log"
EVENTS = ROOT / "actual-writer-controller-events.jsonl"
FAIL = ROOT / "actual-writer-failed"
FINAL = ROOT / "actual-lmdb-final-ack"


def record(event, **fields):
    row = {"time_ns": time.time_ns(), "event": event, **fields}
    with EVENTS.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(row, sort_keys=True) + "\n")
        stream.flush()
        os.fsync(stream.fileno())


def append_witness(path, row):
    with path.open("ab") as stream:
        stream.write((row + "\n").encode("utf-8"))
        stream.flush()
        os.fsync(stream.fileno())


def write_json_exclusive(path, value):
    with path.open("x", encoding="utf-8") as stream:
        stream.write(json.dumps(value, indent=2, sort_keys=True) + "\n")
        stream.flush()
        os.fsync(stream.fileno())


def wait_line(process, log, expected):
    while True:
        line = process.stdout.readline()
        log.write("child=" + line)
        if not line:
            raise RuntimeError("child exited before " + expected + "; exit=" + str(process.poll()))
        normalized = line.strip().removeprefix("CRASHLAB:")
        if normalized == expected:
            return
        if normalized.startswith("COMMIT_RETURNED:") or normalized.endswith("_COMMIT_RETURNED") \
                or normalized.startswith("NAMESPACE_COMMIT_RETURNED:"):
            raise RuntimeError("unexpected child event: " + normalized)


def stop_child(process):
    if process is None:
        return
    if process.poll() is None:
        process.kill()
        process.wait(timeout=10)
    for stream in (process.stdin, process.stdout):
        if stream is not None:
            stream.close()


def fail(message, processes=()):
    with LOG.open("a", encoding="utf-8") as stream:
        stream.write("FAIL: " + message + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    record("FAIL", message=message)
    with FAIL.open("x", encoding="utf-8") as stream:
        stream.write(message + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    for process in processes:
        stop_child(process)


def main():
    for path in (WITNESS, NAMESPACE_WITNESS, LOG, EVENTS, FAIL, FINAL,
                 ROOT / "actual-writer-controller.json"):
        if path.exists():
            raise FileExistsError("refusing preexisting writer artifact: " + str(path))
    WITNESS.open("xb").close()
    NAMESPACE_WITNESS.open("xb").close()
    baseline = post = None
    with LOG.open("x", encoding="utf-8", buffering=1) as log, EVENTS.open("x", encoding="utf-8"):
        log.write("guest_writer_controller_start\n")
        java = "/usr/bin/java"
        main_class = "org.eclipse.rdf4j.sail.lmdb.LmdbCrashRecoveryTest$CrashWriterMain"
        command = [java, "-cp", CP, main_class, "/mnt/crash-data/store", "NONE", "10485760"]
        log.write("baseline_command=" + json.dumps(command) + "\n")
        baseline = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                    stderr=subprocess.STDOUT, text=True, bufsize=1)
        record("BASELINE_CHILD_START", pid=baseline.pid)
        try:
            wait_line(baseline, log, "READY")
            wait_line(baseline, log, "ROLLED_BACK")
            if len(BASE_EXPECTED) != 3:
                raise RuntimeError("expected exactly three baseline witness records")
            for index, expected_record in enumerate(BASE_EXPECTED):
                transaction_id = expected_record.split("\t", 1)[0]
                wait_line(baseline, log, "COMMIT_RETURNED:" + transaction_id)
                append_witness(WITNESS, expected_record)
                record("WITNESS_FSYNCED_AFTER_BASELINE_COMMIT", transaction_id=transaction_id,
                       index=index + 1)
                baseline.stdin.write("CONTINUE\n")
                baseline.stdin.flush()
            code = baseline.wait(timeout=120)
            if code != 0:
                raise RuntimeError("baseline writer failed during orderly close; exit=" + str(code))
            record("BASELINE_STORE_CLOSED", exit_code=code)

            post_class = "org.eclipse.rdf4j.sail.lmdb.CrashPostBaselineWriterMain"
            post_command = [java, "-cp", CP, post_class, "/mnt/crash-data/store"]
            log.write("post_baseline_command=" + json.dumps(post_command) + "\n")
            post = subprocess.Popen(post_command, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                    stderr=subprocess.STDOUT, text=True, bufsize=1)
            record("POST_BASELINE_CHILD_START", pid=post.pid)
            wait_line(post, log, "POST_BASELINE_READY")
            for expected_event, expected_witness in (
                    ("RETIREMENT_DELETE_COMMIT_RETURNED", FOLLOWUP_EXPECTED[0]),
                    ("RETIREMENT_READD_COMMIT_RETURNED", FOLLOWUP_EXPECTED[1])):
                wait_line(post, log, expected_event)
                append_witness(WITNESS, expected_witness)
                record("WITNESS_FSYNCED_AFTER_POST_BASELINE_COMMIT", child_event=expected_event,
                       witness_record=expected_witness)
                post.stdin.write("CONTINUE\n")
                post.stdin.flush()
            namespace = FOLLOWUP_EXPECTED[2]
            namespace_value = namespace.split("\t", 1)[1]
            wait_line(post, log, "NAMESPACE_COMMIT_RETURNED:" + namespace_value)
            append_witness(WITNESS, namespace)
            append_witness(NAMESPACE_WITNESS, namespace)
            record("NAMESPACE_WITNESS_FSYNCED_AFTER_COMMIT_RETURNED", witness_record=namespace)
            with FINAL.open("x", encoding="utf-8") as marker:
                marker.write("namespace-only commit returned; independent witness was fsynced; guest remains unsynced\n")
                marker.flush()
                os.fsync(marker.fileno())
            record("FINAL_ACK_MARKER_FSYNCED", witness_records=6, process=post.pid,
                   state="namespace writer blocked before store shutdown")
            write_json_exclusive(ROOT / "actual-writer-controller.json",
                                 {"baseline_pid": baseline.pid, "post_baseline_pid": post.pid,
                                  "baseline_witness_records": 3, "followup_witness_records": 3,
                                  "state": "namespace writer blocked before store shutdown"})
            while True:
                time.sleep(1)
        except BaseException as error:
            fail(type(error).__name__ + ": " + str(error), (baseline, post))
            raise


if __name__ == "__main__":
    main()
